contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an input depositAmt to send to c.deposit, and a second gas-limited attempt to observe behavior.
    function run(uint depositAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmt);

        // Record c balance before any action
        uint beforeC = address(c).balance;

        // Make a deposit into c from this contract
        c.deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // Now attempt withdrawAll and record if it reverts
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After withdraw attempt, observe c balance
        uint afterC = address(c).balance;

        // Try a second withdraw to observe whether any further funds are transferred
        // We cannot directly observe transferred amount except via c's balance change.
        bool reverted2;
        uint beforeSecond = afterC;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }
        uint afterSecond = address(c).balance;

        // Read: We assert that withdrawAll clearing credit is equivalent to first call succeeding (not reverting).
        // We express "observed credit becomes zero" by requiring that a second withdraw does not decrease c's balance further
        // (i.e., no additional transfer). So: first call succeeded iff second call did NOT further decrease c.balance.
        // Also assert that when the first withdraw succeeded, c's balance did not increase as a result of that call.

        assert(
            // equivalence: first withdraw success <=> second call does not further decrease c.balance
            ((reverted == false) == (afterSecond >= beforeSecond))
            // and if first withdraw succeeded then afterC is <= beforeC (c didn't gain balance from withdraw)
            && (reverted == true || afterC <= beforeC)
        );
    }

    receive() external payable { }
}

