pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        uint beforeC = address(c).balance;
        try c.deposit{value: depositAmt}() {} catch { return; }
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        bool reverted2;
        uint beforeSecond = afterC;
        try c.withdrawAll() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        uint afterSecond = address(c).balance;
        assertTrue(((reverted == false) == (afterSecond >= beforeSecond))
            // and if first withdraw succeeded then afterC is <= beforeC (c didn't gain balance from withdraw)
            && (reverted == true || afterC <= beforeC));
    }

    function testFuzz_run(uint256 depositAmt) public {
        _run(depositAmt);
    }

    receive() external payable { }
}
